/**
 * 학년·학기별 급수표 — 교사가 아무것도 만들지 않아도 오늘 바로 수업이 되게.
 *
 * 🔴 왜 앱에 넣었나: 「급수표는 선생님이 만들어 쓰세요」는 앱이 일을 떠넘기는 것이다.
 * 학교마다 급수표가 다르다는 건 사실이지만, 그건 «고쳐 쓸 수 있게» 하면 되는 문제이지
 * 백지를 내밀 이유가 아니다. 그래서 학년·학기별로 전부 만들어 넣고, 교사는 필요하면
 * 담아서 고친다.
 *
 * 문항은 2022 개정 국어과의 흐름을 따라 직접 썼다(교과서 문장을 옮기지 않았다):
 *   1학년 = 자모·받침 있는 낱말 → 소리와 표기가 다른 낱말 → 짧은 문장
 *   2학년 = 문장·띄어쓰기·문장부호 → 겹받침·된소리
 *   3학년 = 긴 문장·사이시옷·구개음화·준말
 *   4~6학년 = 자주 틀리는 맞춤법(되/돼, 안/않, 로서/로써 …)과 문장 구조
 *
 * 음원은 이 파일의 id 를 그대로 경로로 쓴다: `audio/<id>/<두 자리 번호>.mp3`
 * (빌드 때 미리 구워 둔다 — 브라우저 목소리에 기대지 않는다.)
 */

export interface LevelSheet {
  id: string;
  grade: 1 | 2 | 3 | 4 | 5 | 6;
  semester: 1 | 2;
  level: number;
  title: string;
  point: string;
  items: string[];
}

