    items: ['약속한 밤에 밤을 간식으로 먹었습니다.', '눈이 내리자 친구의 눈이 더욱 반짝였습니다.', '배를 타기 전에 배가 고파서 간식을 먹었습니다.', '말을 타면서 친구의 말을 귀담아들었습니다.', '차를 마신 뒤 차를 타고 약속 장소로 갔습니다.', '사과를 건네며 늦은 일을 정중히 사과했습니다.', '벌을 보느라 약속 시간을 어겨 벌을 받았습니다.', '김이 나는 국을 먹다가 친구 김 군을 만났습니다.', '다음 날 날이 밝으면 다시 만나기로 했습니다.', '시간을 세는 동안 새 세 마리가 날아갔습니다.'],
