    items: ['친구와 시간을 맞추어 운동장에 모였습니다.', '문제의 정답을 맞힌 친구가 활짝 웃었습니다.', '시곗바늘을 정확한 시각에 맞추어 보세요.', '동생은 수수께끼의 답을 단번에 맞혔습니다.', '모둠원끼리 발표 순서를 서로 맞추었습니다.', '선생님의 질문을 잘 듣고 답을 맞혀 봅시다.', '짝과 발걸음을 맞추며 천천히 걸었습니다.', '민수는 퀴즈 다섯 문제를 모두 맞혔습니다.', '우리는 책상 줄을 가지런히 맞추어 놓았습니다.', '누가 정답을 맞힐지 친구들이 궁금해했습니다.'],
