    items: ['선생님은 “씨앗을 자세히 살펴보세요.”라고 하셨어요.', '아빠가 “화분에 물을 조금만 주렴.”이라고 말했어.', '친구는 “봉오리가 곧 활짝 피겠어.”라고 했습니다.', '동생이 “이 꽃에서는 좋은 향기가 나!”라고 외쳤어.', '누나는 “잎의 뒷면도 관찰해 봐.”라고 알려 주었지.', '할머니께서 “상추가 많이 자랐구나.”라고 말씀하셨어.', '친구가 “민들레 씨가 바람에 날아가네.”라고 말했어요.', '형은 “새싹이 어제보다 더 자랐어.”라고 이야기했지.', '선생님께서 “줄기의 길이를 재어 보자.”라고 하셨어요.', '엄마는 “마른 잎을 먼저 떼어 내자.”라고 말씀하셨지.'],
