    items: ['과학자는 실험을 통해 새로운 사실을 발견합니다.', '발명가는 생활의 불편을 해결할 방법을 연구합니다.', '관찰한 내용을 기록하면 변화를 비교하기 쉽습니다.', '새로운 장치는 여러 번의 실험을 거쳐 완성됩니다.', '자석의 성질을 이용하면 물체를 움직일 수 있습니다.', '기계의 구조를 살펴보며 작동 원리를 알아봅시다.', '전기는 우리 생활에 필요한 중요한 에너지입니다.', '온도를 측정하여 물질의 변화를 확인했습니다.', '안전을 위해 실험 기구를 올바르게 사용해야 합니다.', '아이디어를 구체적인 모형으로 만들어 보았습니다.'],
