    items: ['“정말 기뻐!” 동생이 활짝 웃으며 말했습니다.', '마음이 답답할 때, 너는 어떻게 풀어 내니?', '“괜찮아, 다시 해 보자.”라는 말에 힘이 났습니다.', '기쁨, 슬픔, 놀람은 모두 자연스러운 감정입니다.', '갑자기 큰 소리가 났어요! 깜짝 놀랐나요?', '“왜 화가 났어?” 친구가 조심스럽게 물었습니다.', '걱정이 사라지자, 마음이 한결 가벼워졌어요!', '친구의 위로를 들으니 기분이 좋아졌어요. 고마워!', '속상한 일이 있나요? “말해도 괜찮아.”라고 해 주세요.', '마음속에 여러 감정이 있어요. 참 신기하지요?'],
