    items: ['교실 앞에 웬 친구가 나를 기다리고 있지?', '오늘은 왠지 친구에게 먼저 인사하고 싶어.', '운동장에 웬 낯선 친구가 혼자 서 있나요?', '짝꿍을 보니 왠지 기분이 좋아졌습니다.', '책상 위에 웬 친구의 쪽지가 놓여 있었어.', '친구의 표정을 보니 왠지 걱정이 되었지.', '복도에서 웬 친구가 급하게 달려오는 걸까?', '전학생과 이야기하니 왠지 금방 친해질 듯해.', '가방 속에 웬 우정 카드가 들어 있네요.', '친구가 웃으니 왠지 나도 따라 웃게 되었어.'],
