    items: ['친구와 입맛을 맞추어 샌드위치를 만들었어요.', '나는 눈을 감고 과일의 이름을 맞혔습니다.', '그릇의 크기에 맞추어 떡을 알맞게 담았어요.', '동생은 냄새만 맡고 딸기를 바로 맞혔어.', '가족의 식사 시간에 맞추어 밥을 지었습니다.', '누가 상자 속 과자의 종류를 맞힐 수 있을까요?', '양념의 간을 입맛에 맞추니 훨씬 맛있었어요.', '형은 재료만 보고 어떤 국인지 맞혔지.', '접시의 무늬에 맞추어 과일을 가지런히 놓았어.', '나는 맛을 보고 들어간 채소를 모두 맞혔습니다.'],
