    items: ['농부는 밭에서 일하며 새참으로 밤을 먹었어요.', '밤이 깊어도 경비원은 건물을 안전하게 지킵니다.', '목수는 나무를 자로 재고 자를 곳에 표시했어요.', '화가는 붓으로 붓꽃의 모습을 곱게 그렸습니다.', '기자는 기사를 쓰려고 사자에 관한 자료를 찾았어.', '사육사는 사자에게 먹이를 주며 상태를 살폈지.', '선생님은 반 아이들에게 반듯한 글씨를 가르쳐요.', '재봉사는 옷감을 실로 꿰며 실력을 발휘했습니다.', '정원사는 배나무를 돌본 뒤 달콤한 배를 먹었어요.', '어부는 그물에 잡힌 조기를 보고 조기에 돌아왔지.'],
