    items: ['명절에 먹는 떡을 직접 만들어 보았어요.', '나는 어른께 인사하는 법을 배워 보았습니다.', '할머니가 전통 놀이 방법을 알려 주셨어요.', '동생은 고운 한복을 입어 보고 활짝 웃었지.', '온 가족이 둘러앉아 이야기를 나누어 보자!', '윷가락을 상자에 가지런히 넣어 두었어요.', '우리 모둠은 제기차기를 함께 연습해 보았지.', '아빠가 오래된 전통 악기를 꺼내 보여 주셨어요.', '명절 음식을 이웃과 조금씩 나누어 먹었어요.', '친구와 팽이를 힘차게 돌려 보았습니다.'],
