    items: ['친구가 “내 우산을 함께 쓰자.”라고 말했어요.', '선생님은 “서로 양보하며 지내자.”라고 하셨어요.', '동생이 “내가 짐을 들어 줄게.”라고 말했습니다.', '할머니는 “고운 마음이 참 기특하구나.”라고 하셨어.', '짝꿍이 “연필을 빌려줄까?”라고 물어보았어요.', '아이는 “제 자리를 양보할게요.”라고 말했지.', '형이 “남은 간식을 함께 나누자.”라고 제안했어요.', '친구는 “기다려 줘서 정말 고마워.”라고 했습니다.', '엄마가 “동생의 이야기도 들어 주렴.”이라고 하셨어.', '누나는 “무거운 상자를 같이 옮기자.”라고 말했지.'],
