    items: ['의사는 환자의 건강을 살피고 치료합니다.', '작가는 풍부한 상상력으로 작품을 창작합니다.', '농부는 작물의 상태를 관찰하며 재배합니다.', '요리사는 신선한 재료를 선택해 조리합니다.', '소방관은 화재를 진압하고 사람을 구조합니다.', '기자는 현장을 취재하여 정확한 정보를 전달합니다.', '연구원은 새로운 지식을 얻으려고 실험합니다.', '건축가는 안전한 건물을 세우도록 설계합니다.', '교사는 학생의 성장을 돕고 학습을 지도합니다.', '수의사는 동물의 질병을 검사하고 치료하지요.'],
