    items: ['동생아, 우산을 가져갈래? 비가 올 것 같아.', '누나는 “우아, 정말 멋지다!” 하고 감탄했습니다.', '어머니, 제가 설거지를 할까요? 맡겨 주세요!', '아빠, 오늘 저녁은 무엇을 먹을까요? 제가 도울게요!', '형이 “잠깐, 내 이야기도 들어 줘!”라고 말했어.', '할머니, 이 사진 기억나세요? 정말 재미있었죠!', '아버지가 “그래, 함께 해 보자!” 하며 웃으셨어.', '언니야, 지금 시간 괜찮아? 같이 산책하자!', '동생이 “앗, 내 양말이 어디 갔지?”라고 물었어.', '엄마, 이 상자 열어 봐도 돼요? 궁금해요!'],
