    items: ['토끼는 긴 뒷다리로 힘차게 뛰어갑니다.', '고래가 수면 위로 올라와 크게 숨을 쉽니다.', '다람쥐는 나무 위에서 도토리를 먹고 있습니다.', '기린의 긴 목은 높은 나뭇잎에 쉽게 닿습니다.', '개미들이 먹이를 힘을 모아 집으로 옮깁니다.', '부엉이는 밤이 되면 먹이를 찾아 움직입니다.', '펭귄의 두꺼운 깃털은 추위를 견디게 해 줍니다.', '나비가 꽃 사이를 날며 꿀을 찾아다닙니다.', '수달은 물속에서 빠르고 능숙하게 헤엄칩니다.', '달팽이가 촉수를 내밀며 천천히 기어갑니다.'],
