    items: ['국은 뜨거웠지만 그래도 천천히 맛을 보았습니다.', '과일을 씻고 나서 먹기 좋은 크기로 잘랐어요.', '채소는 신선하고 게다가 아삭한 맛도 좋습니다.', '배가 고팠으므로 먼저 간단한 음식을 먹었지요.', '나는 매운맛을 좋아하지만 동생은 단맛을 좋아해요.', '재료를 준비한 뒤에 냄비에 차례대로 넣었습니다.', '간식도 맛있지만 너무 많이 먹으면 배가 부릅니다.', '채소를 골고루 먹으면 몸에 좋으므로 자주 먹읍시다.', '요리가 완성되었습니다. 그래서 가족을 불렀어요.', '처음에는 낯선 맛이었으나 자꾸 먹으니 익숙해졌습니다.'],
