    items: ['이웃들이 힘을 모으자 어려운 일도 쉽게 풀렸습니다.', '마을 잔치를 앞두고 모두가 팔을 걷어붙였어요.', '길을 잃은 아이를 보고 주민들이 발 벗고 나섰습니다.', '새 놀이터가 생긴다는 소식에 귀가 번쩍 뜨였지요.', '가게 주인은 손님을 맞느라 눈코 뜰 새가 없었습니다.', '동네 친구들은 오랜만에 만나 이야기꽃을 피웠어요.', '골목을 깨끗이 치우자 주민들의 얼굴이 활짝 폈습니다.', '우리 마을 소식이라면 할머니께서 귀가 밝으시지요.', '시장에 사람이 몰리자 상인들은 손이 모자랐습니다.', '이웃 어른은 어려운 부탁에도 선뜻 손을 내밀었어요.'],
