    items: ['숲을 걸은 지 한 시간 만에 작은 연못을 만났습니다.', '우리는 나무 한 그루씩 정성껏 심어 보았어요.', '비가 그친 뒤 맑은 하늘이 조금씩 드러났습니다.', '강가에 버려진 쓰레기를 주워 한곳에 모았지요.', '나뭇잎이 떨어질 때마다 길 위에 차곡차곡 쌓입니다.', '환경을 지키기 위해 할 수 있는 일을 찾아보세요.', '산길을 걷는 동안 새소리를 여러 번 들었습니다.', '물을 아껴 쓰는 것부터 오늘 바로 실천해 봅시다.', '작은 화분 두 개를 햇볕이 드는 곳에 놓았어요.', '바람이 불 것 같아서 열린 창문을 미리 닫았습니다.'],
