    items: ['약속 시간보다 십 분 먼저 도착했어요.', '우리 내일 몇 시에 만나기로 했지?', '앗, 벌써 출발할 시간이 다 되었구나!', '수업이 끝나면 도서관 앞에서 만납시다.', '혹시 약속 날짜를 다시 알려 줄래요?', '와, 이번에는 모두 제시간에 모였네요!', '늦지 않으려면 지금 출발해야 하지 않을까?', '친구를 기다리며 시계를 자꾸 확인했습니다.', '자, 정해진 시간까지 준비를 마치세요!', '내일 약속을 잊지 않도록 달력에 적어 둘게요.'],
