    items: ['따뜻한 햇살에 꽃봉오리가 활짝 벌어졌습니다.', '농부는 어린 모종을 밭에서 잘 자라게 했어요.', '거센 바람에 가느다란 나뭇가지가 꺾였습니다.', '햇빛은 덜 익은 열매를 빨갛게 익게 합니다.', '화분에 심긴 씨앗에서 작은 싹이 돋아났지요.', '정원사는 덩굴이 울타리를 타고 오르게 했습니다.', '비바람에 꽃잎이 떨어져 땅 위에 흩어졌어요.', '나는 시든 화초에 물을 주어 다시 살아나게 했습니다.', '숲길은 키 큰 나무들로 빽빽하게 둘러싸였지요.', '할머니는 봉오리가 맺힌 화분을 창가로 옮기게 하셨어요.'],
