    items: ['우리 가족의 여행지는 조용한 바닷가 마을입니다.', '여행을 떠나는 날이 드디어 내일로 다가왔어요.', '기차가 출발하는 시각은 아침 아홉 시입니다.', '내가 가장 기대하는 것은 숲길을 걷는 일이지요.', '여행 가방의 무게가 생각보다 많이 늘었습니다.', '우리는 낯선 길에서도 안내판을 꼼꼼히 살펴보았어요.', '숙소에서 바라본 풍경은 마음을 편안하게 합니다.', '이번 여행의 목적은 자연을 가까이 느끼는 것입니다.', '산책로를 걷는 사람들이 천천히 전망대로 향했지요.', '내일의 날씨가 여행 일정을 바꿀 수도 있습니다.'],
