    items: ['소방관은 위험한 곳에서 사람들을 구조합니다.', '요리사는 여러 가지 재료로 음식을 만듭니다.', '우리 아버지는 일주일에 다섯 번 출근하십니다.', '동물 의사는 아픈 동물을 정성껏 치료합니다.', '과학자는 오랜 시간 새로운 현상을 연구합니다.', '농부는 이른 아침부터 논과 밭을 돌봅니다.', '나는 장래 희망에 대해 친구와 이야기했습니다.', '환경 미화원은 거리를 깨끗하게 청소합니다.', '방송 작가는 여러 사람과 함께 대본을 씁니다.', '제빵사는 갓 구운 빵을 진열대에 올려놓습니다.'],
