    items: ['아빠, 오늘 저녁에는 함께 산책할까요?', '와, 동생이 혼자서 방을 깨끗이 정리했어요!', '우리 가족은 주말마다 함께 아침을 먹습니다.', '엄마, 제가 설거지를 도와드릴까요?', '앗, 할머니께 드릴 편지를 두고 왔어요!', '형은 오늘 몇 시쯤 집에 돌아오나요?', '자, 가족사진을 찍을 테니 모두 모이세요!', '누나는 동생에게 재미있는 책을 읽어 줍니다.', '어머, 아빠가 벌써 저녁을 준비하셨네요!', '할아버지, 오늘은 어떤 이야기를 들려주실래요?'],
